package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.asof.AsOfView;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class RateRepository {

    private static final String COLUMNS = "SELECT sheet_id, grade, pct, from_date, to_date, version, claims_after FROM rate ";

    private static final RowMapper<Rate> ROW = (rs, n) -> {
        LocalDate from = rs.getObject("from_date", LocalDate.class);
        LocalDate to = rs.getObject("to_date", LocalDate.class);
        return new Rate(rs.getString("sheet_id"), rs.getString("grade"),
                rs.getBigDecimal("pct").setScale(2).toPlainString(), from == null ? null : from.toString(),
                to == null ? null : to.toString(), 0, rs.getInt("version"), rs.getObject("claims_after", Long.class), null);
    };

    /** How many levels up the parent chain a sheet without a rate of its own looks. */
    public static final int LEVELS = 3;

    private final JdbcTemplate jdbc;

    public RateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's own rates (level 0), by grade, then by from-date (none first), then those of its
     *  parent, its parent's parent, up to {@link #LEVELS} up, each at its level. A grade without a rate
     *  is not listed. While the sheet is shown as of a date, its ancestors' rates are as they stood then. */
    public List<Rate> list(String sheetId) {
        List<Rate> all = new ArrayList<>(own(sheetId));
        List<String> chain = ancestors(sheetId);
        LocalDate asOf = AsOfView.schema() == null ? null
                : jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
                        .stream().filter((d) -> d != null).findFirst().orElse(null);
        for (int i = 0; i < chain.size(); i++) {
            int level = i + 1;
            (asOf == null ? own(chain.get(i)) : ownAsOf(chain.get(i), asOf)).forEach((r) -> all.add(r.at(level)));
        }
        return all;
    }

    private List<Rate> own(String sheetId) {
        return withPriors(jdbc.query(COLUMNS + "WHERE sheet_id = ? ORDER BY grade, from_key", ROW, sheetId));
    }

    /** Each forward-only rate given the version it replaced (and that one its own, while forward-only). */
    private List<Rate> withPriors(List<Rate> rates) {
        List<Rate> all = new ArrayList<>();
        for (Rate r : rates) {
            if (r.claimsAfter() == null) {
                all.add(r);
                continue;
            }
            List<Rate> older = jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, version, claims_after "
                    + "FROM rate_version WHERE sheet_id = ? AND grade = ? AND from_key = COALESCE(CAST(? AS DATE), "
                    + "DATE '0001-01-01') AND version < ? ORDER BY version DESC", ROW,
                    r.sheetId(), r.grade(), r.from() == null ? null : LocalDate.parse(r.from()), r.version());
            all.add(chain(r, older, 0));
        }
        return all;
    }

    private static Rate chain(Rate rate, List<Rate> older, int next) {
        if (rate.claimsAfter() == null || next >= older.size()) return rate;
        return rate.withPrior(chain(older.get(next), older, next + 1));
    }

    /** The sheet's parent, its parent's parent, ... up to {@link #LEVELS} up (stopping at a sheet named twice). */
    public List<String> ancestors(String sheetId) {
        List<String> chain = new ArrayList<>();
        String at = sheetId;
        while (chain.size() < LEVELS) {
            at = parent(at);
            if (at == null || at.equals(sheetId) || chain.contains(at)) break;
            chain.add(at);
        }
        return chain;
    }

    /** The sheet's parent sheet id; null when it has none. */
    public String parent(String sheetId) {
        return jdbc.queryForList("SELECT val FROM sheet_setting WHERE sheet_id = ? AND setting = 'parent'",
                String.class, sheetId).stream().filter((v) -> v != null && !v.isEmpty()).findFirst().orElse(null);
    }

    /** The grade's rate for the sheet that applies to the claim (by its id) on the date: the sheet's own
     *  with the latest from-date on or before it that applies to the claim, unless there is none or it
     *  ended (its to-date) before the date, when its parent's is looked up the same way, and so on up to
     *  {@link #LEVELS} up; null when none has one. */
    public Rate find(String sheetId, String grade, LocalDate on, long claimId) {
        return inForce(list(sheetId), grade, on.toString(), claimId);
    }

    /** The sheet's rates as they stood at the end of the date: each as the last rate set while the
     *  sheet's today was on or before the date left it, by grade, then by from-date (none first). */
    public List<Rate> listAsOf(String sheetId, LocalDate asOf) {
        List<Rate> all = new ArrayList<>(ownAsOf(sheetId, asOf));
        List<String> chain = ancestors(sheetId);
        for (int i = 0; i < chain.size(); i++) {
            int level = i + 1;
            ownAsOf(chain.get(i), asOf).forEach((r) -> all.add(r.at(level)));
        }
        return all;
    }

    private List<Rate> ownAsOf(String sheetId, LocalDate asOf) {
        return withPriors(jdbc.query("SELECT sheet_id, grade, pct, from_date, to_date, version, claims_after FROM rate_history h WHERE h.sheet_id = ? "
                + "AND h.id = (SELECT MAX(h2.id) FROM rate_history h2 WHERE h2.sheet_id = h.sheet_id AND h2.grade = h.grade "
                + "AND h2.from_key = h.from_key AND (h2.on_date IS NULL OR h2.on_date <= ?)) ORDER BY grade, from_key",
                ROW, sheetId, asOf));
    }

    /** The grade's rate among {@code rates} in force on the date (yyyy-MM-dd), as {@link #find} finds it:
     *  the nearest level that has one in force then. */
    public static Rate inForce(List<Rate> rates, String grade, String date) {
        return inForce(rates, grade, date, null);
    }

    /** The grade's rate among {@code rates} that applies to the claim (by its id) on the date (yyyy-MM-dd),
     *  as {@link #inForce(List, String, String)} finds it among the versions that apply to the claim
     *  (a forward-only rate saved after the claim was added does not; the one it replaced may). */
    public static Rate inForce(List<Rate> rates, String grade, String date, long claimId) {
        return inForce(rates, grade, date, Long.valueOf(claimId));
    }

    private static Rate inForce(List<Rate> rates, String grade, String date, Long claimId) {
        for (int level = 0; level <= LEVELS; level++) {
            Rate found = null;
            for (Rate listed : rates) {
                Rate r = claimId == null ? listed : listed.forClaim(claimId);
                if (r == null || r.level() != level || !r.grade().equals(grade) || (r.from() != null && r.from().compareTo(date) > 0)) continue;
                if (found == null || (found.from() == null ? "" : found.from()).compareTo(r.from() == null ? "" : r.from()) < 0) found = r;
            }
            if (found != null && !found.endedBefore(date)) return found;
        }
        return null;
    }

    /** Set the grade's rate from the from-date (null: from the beginning of time) through the to-date
     *  (null: no end). When the grade already has a rate from that from-date, the one it replaces is kept
     *  as an older version and the new one is the next version (the one in force). A from-date on or after
     *  the sheet's today makes it forward-only: it applies only to claims added after now. */
    public Rate set(String sheetId, String grade, BigDecimal pct, LocalDate from, LocalDate to, String user) {
        String match = "sheet_id = ? AND grade = ? AND from_key = COALESCE(CAST(? AS DATE), DATE '0001-01-01')";
        LocalDate today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", LocalDate.class, sheetId)
                .stream().filter((d) -> d != null).findFirst().orElse(LocalDate.now());
        Long claimsAfter = from == null || from.isBefore(today) ? null
                : jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM claim", Long.class);
        jdbc.update("INSERT INTO rate_version (sheet_id, grade, version, pct, from_date, to_date, set_by, set_at, claims_after) "
                + "SELECT sheet_id, grade, version, pct, from_date, to_date, set_by, set_at, claims_after FROM rate WHERE " + match,
                sheetId, grade, from);
        int version = 1 + jdbc.queryForList("SELECT version FROM rate WHERE " + match, Integer.class, sheetId, grade, from)
                .stream().findFirst().orElse(0);
        jdbc.update("DELETE FROM rate WHERE " + match, sheetId, grade, from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, pct, from_date, to_date, set_by, set_at, version, claims_after) "
                + "VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?, ?)", sheetId, grade, pct, from, to, user, version, claimsAfter);
        jdbc.update("INSERT INTO rate_history (sheet_id, grade, pct, from_date, to_date, on_date, version, claims_after) "
                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)",
                sheetId, grade, pct, from, to, sheetId, version, claimsAfter);
        return new Rate(sheetId, grade, pct.toPlainString(), from == null ? null : from.toString(),
                to == null ? null : to.toString(), 0, version, claimsAfter, null);
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimNumbers;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/**
 * Copies a sheet into a new, never used one. The clone gets the sheet's today, settings, roles, rates,
 * holidays, void reasons, templates and tags, its people (with their grades, terms, contacts, aliases,
 * holds, retirements and patrons), pools with their members, crews with their members, periods (all open, their fixed totals
 * dropped) and claims (with their status, frozen figures, dates, notes, tags, logs and comments) and
 * the history the sheet keeps of them. Statements are not copied: every statement count starts at 0
 * and no figure a statement bound is kept. Watches, delegations, claim locks and settle batches are not
 * copied either. Each claim that had a number gets the clone's next, by the clone's own numbering, in
 * the order the originals were opened (by the sheet's today then, then the order they were added).
 */
@Repository
public class SheetCloner {

    private final JdbcTemplate jdbc;

    /** The columns of each table the store fills itself (generated or identity), by table. */
    private final Map<String, List<String>> filled = new HashMap<>();

    public SheetCloner(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void cloneSheet(String from, String to, String user, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets) {
        jdbc.update("INSERT INTO sheet (id, created_by, today) SELECT ?, ?, today FROM sheet WHERE id = ?",
                to, user, from);
        Map<String, Object> none = Map.of();
        for (String table : List.of("sheet_setting", "setting_history", "sheet_role", "rate", "rate_history", "rate_version",
                "holiday", "void_reason", "claim_template", "sheet_tag")) {
            copy(table, from, to, Map.of(), none);
        }
        Map<String, Object> unstated = new HashMap<>();
        unstated.put("statement_count", 0);
        unstated.put("stated_total", null);
        unstated.put("statement_date", null);
        unstated.put("arrived_on", null); // a clone did not arrive by transfer: nothing there to undo
        unstated.put("version", 0);
        Map<Long, Long> people = copy("person", from, to, Map.of(), unstated);
        Map<String, Map<Long, Long>> byPerson = Map.of("person_id", people);
        for (String table : List.of("person_grade", "person_terms", "person_grade_history", "person_retired_history",
                "person_retirement", "person_hold", "person_alias")) {
            copy(table, from, to, byPerson, none);
        }
        copy("person_patron", from, to, Map.of("person_id", people, "patron_id", people), none);

        Map<Long, Long> pools = copy("pool", from, to, Map.of(), none);
        Map<String, Map<Long, Long>> members = new HashMap<>();
        members.put("pool_id", pools);
        members.put("person_id", people);
        members.put("member_pool_id", pools);
        copy("pool_member", from, to, members, none);

        Map<Long, Long> crews = copy("crew", from, to, Map.of("lead_id", people), none);
        copy("crew_member", from, to, Map.of("crew_id", crews, "person_id", people), none);

        Map<String, Object> open = new HashMap<>();
        open.put("closed", false);
        open.put("soft_closed", false);
        open.put("closed_total", null);
        open.put("closed_by", null);
        open.put("closed_at", null);
        copy("period", from, to, Map.of(), open);

        Map<String, Object> fresh = new HashMap<>();
        fresh.put("number", null);
        fresh.put("stated", false);
        fresh.put("stated_due", null);
        fresh.put("locked_by", null);
        fresh.put("settle_batch", null);
        Map<Long, Long> copied = copy("claim", from, to, byPerson, fresh);
        Map<String, Map<Long, Long>> byClaim = Map.of("claim_id", copied);
        copy("claim_log", from, to, byClaim, none);
        copy("claim_comment", from, to, byClaim, none);
        copy("claim_line", from, to, byClaim, none);
        Map<String, Object> unbound = new HashMap<>();
        unbound.put("stated", false);
        unbound.put("stated_due", null);
        copy("claim_history", from, to, Map.of("claim_id", copied, "person_id", people), unbound);

        // A forward-only rate applies to the claims added after it was saved: the copies of those now.
        for (String table : List.of("rate", "rate_version", "rate_history")) {
            for (Long after : jdbc.queryForList("SELECT DISTINCT claims_after FROM " + table
                    + " WHERE sheet_id = ? AND claims_after IS NOT NULL", Long.class, to)) {
                long now = copied.entrySet().stream().filter((e) -> e.getKey() <= after)
                        .mapToLong(Map.Entry::getValue).max().orElse(0);
                jdbc.update("UPDATE " + table + " SET claims_after = ? WHERE sheet_id = ? AND claims_after = ?",
                        -now - 1, to, after);
            }
            jdbc.update("UPDATE " + table + " SET claims_after = -claims_after - 1 WHERE sheet_id = ? "
                    + "AND claims_after < 0", to);
        }

        // Number afresh, in the order the originals were opened, by the clone's own numbering.
        Map<String, String> numbers = new HashMap<>();
        for (Map<String, Object> row : jdbc.queryForList("SELECT c.id, c.number FROM claim c "
                + "JOIN person p ON p.id = c.person_id WHERE c.sheet_id = ? AND c.number IS NOT NULL "
                + "ORDER BY COALESCE((SELECT MIN(l.on_date) FROM claim_log l WHERE l.claim_id = c.id AND "
                + "l.status = 'OPEN'), (SELECT MIN(l.on_date) FROM claim_log l WHERE l.claim_id = c.id AND "
                + "l.status <> 'DRAFT'), c.claim_date), p.list_pos, p.id, c.id", from)) {
            Claim claim = claims.find(to, copied.get(((Number) row.get("id")).longValue()));
            claims.renumber(claim, ClaimNumbers.next(claim, claims, periods, settings, sheets));
            numbers.put((String) row.get("number"), claim.getNumber());
        }
        // A correction or a split names the claim it came from by its number: by its new one now.
        for (String column : List.of("corrects", "split_from")) {
            for (Map<String, Object> row : jdbc.queryForList("SELECT id, " + column + " AS was FROM claim "
                    + "WHERE sheet_id = ? AND " + column + " IS NOT NULL", to)) {
                String now = numbers.get((String) row.get("was"));
                jdbc.update("UPDATE claim SET " + column + " = ? WHERE sheet_id = ? AND id = ?",
                        now, to, row.get("id"));
            }
        }
    }

    /** Copy the sheet's rows of the table to the clone, in the order they were added: each id column in
     *  {@code remap} given the clone's id for it (a row whose id has none is left out), each column in
     *  {@code set} that value. The clone's ids of the rows copied, by the original's, when they have one. */
    private Map<Long, Long> copy(String table, String from, String to, Map<String, Map<Long, Long>> remap,
            Map<String, Object> set) {
        List<String> skip = filled(table);
        boolean keyed = skip.contains("id");
        Map<Long, Long> ids = new LinkedHashMap<>();
        rows:
        for (Map<String, Object> row : jdbc.queryForList("SELECT * FROM " + table + " WHERE sheet_id = ?"
                + (keyed ? " ORDER BY id" : ""), from)) {
            List<String> columns = new ArrayList<>();
            List<Object> values = new ArrayList<>();
            for (Map.Entry<String, Object> column : row.entrySet()) {
                String name = column.getKey().toLowerCase(Locale.ROOT);
                if (skip.contains(name)) continue;
                Object value = column.getValue();
                if (name.equals("sheet_id")) {
                    value = to;
                } else if (set.containsKey(name)) {
                    value = set.get(name);
                } else if (remap.containsKey(name) && value != null) {
                    value = remap.get(name).get(((Number) value).longValue());
                    if (value == null) continue rows;
                }
                columns.add(name);
                values.add(value);
            }
            String sql = "INSERT INTO " + table + " (" + String.join(", ", columns) + ") VALUES ("
                    + String.join(", ", columns.stream().map((c) -> "?").toList()) + ")";
            GeneratedKeyHolder key = new GeneratedKeyHolder();
            jdbc.update(con -> {
                PreparedStatement ps = keyed ? con.prepareStatement(sql, new String[] { "id" }) : con.prepareStatement(sql);
                for (int i = 0; i < values.size(); i++) ps.setObject(i + 1, values.get(i));
                return ps;
            }, key);
            if (keyed) ids.put(((Number) row.get("id")).longValue(), key.getKey().longValue());
        }
        return ids;
    }

    /** The table's columns the store fills itself: generated from other columns, or its identity. */
    private List<String> filled(String table) {
        return filled.computeIfAbsent(table, (t) -> jdbc.queryForList("SELECT LOWER(COLUMN_NAME) FROM "
                + "INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = 'PUBLIC' AND TABLE_NAME = ? AND "
                + "(IS_GENERATED = 'ALWAYS' OR IS_IDENTITY = 'YES')", String.class, t.toUpperCase(Locale.ROOT)));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made (empty, today the real date) if it has never been loaded before. */
    public Sheet open(String id, String user) {
        try {
            jdbc.update("INSERT INTO sheet (id, created_by, today) "
                    + "SELECT ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                    id, user, LocalDate.now(), id);
        } catch (DuplicateKeyException alreadyMade) {
            // another user made it at the same moment: it is there now
        }
        return find(id);
    }

    /** The sheet's descendants: the sheets naming it as their parent (its children), their children,
     *  and so on, each once, nearest first. */
    public java.util.List<String> descendants(String id) {
        java.util.List<String> found = new java.util.ArrayList<>();
        java.util.Set<String> seen = new java.util.HashSet<>(java.util.List.of(id));
        for (int i = -1; i < found.size(); i++) {
            String at = i < 0 ? id : found.get(i);
            for (String child : jdbc.queryForList("SELECT sheet_id FROM sheet_setting WHERE setting = 'parent' "
                    + "AND val = ? ORDER BY sheet_id", String.class, at)) {
                if (seen.add(child)) found.add(child);
            }
        }
        return found;
    }

    /** The sheets of the sheet's tree: its root (the top of its parent chain, stopping at a sheet named
     *  twice) first, then the root's descendants, nearest first. */
    public java.util.List<String> tree(String id) {
        String root = id;
        java.util.Set<String> seen = new java.util.HashSet<>(java.util.List.of(id));
        for (String up = parent(root); up != null && seen.add(up); up = parent(up)) {
            root = up;
        }
        java.util.List<String> tree = new java.util.ArrayList<>(java.util.List.of(root));
        tree.addAll(descendants(root));
        if (!tree.contains(id)) tree.add(id);
        return tree;
    }

    private String parent(String id) {
        return jdbc.queryForList("SELECT val FROM sheet_setting WHERE sheet_id = ? AND setting = 'parent'",
                String.class, id).stream().filter((v) -> v != null && !v.isEmpty()).findFirst().orElse(null);
    }

    /** The sheet's today: the date every date decision and default on the sheet uses. */
    public LocalDate today(String id) {
        Sheet sheet = find(id);
        return sheet == null ? LocalDate.now() : LocalDate.parse(sheet.today());
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }

    /** Whether a steward has archived the sheet (a sheet never loaded is not). */
    public boolean isArchived(String id) {
        Sheet sheet = find(id);
        return sheet != null && sheet.archived();
    }

    public void archive(String id) {
        jdbc.update("UPDATE sheet SET archived = TRUE WHERE id = ?", id);
    }

    /** The sheet's next bulk settle batch number (1, 2, ...), taken atomically; rolled back with the request. */
    public int nextSettleBatch(String id) {
        return jdbc.queryForObject("SELECT last_settle_batch FROM FINAL TABLE (UPDATE sheet SET last_settle_batch = "
                + "COALESCE(last_settle_batch, 0) + 1 WHERE id = ?)", Integer.class, id);
    }

    /** The number of the sheet's last bulk settle batch (null: there has been none). */
    public Integer lastSettleBatch(String id) {
        return jdbc.queryForList("SELECT last_settle_batch FROM sheet WHERE id = ?", Integer.class, id)
                .stream().findFirst().orElse(null);
    }

    public Sheet find(String id) {
        return jdbc.query("SELECT id, created_by, today, archived FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(rs.getString("id"), rs.getString("created_by"),
                        rs.getObject("today", LocalDate.class).toString(), rs.getBoolean("archived")), id)
                .stream().findFirst().orElse(null);
    }
}
